import{_ as e,o as a,c as r,ag as l}from"./chunks/framework.YEBM7mz9.js";const h=JSON.parse('{"title":"React Rehydrate","description":"","frontmatter":{"layout":"doc","aside":false},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(s,t,d,o,c,g){return a(),r("div",null,[...t[0]||(t[0]=[l(`<h1 id="react-rehydrate" tabindex="-1">React Rehydrate <a class="header-anchor" href="#react-rehydrate" aria-label="Permalink to &quot;React Rehydrate&quot;">​</a></h1><p><strong>The Bridge to Modernity: Control High-Performance React 19 Components from your Static Layouts.</strong></p><p><code>react-rehydrate</code> is a professional-grade architectural bridge designed for enterprise ecosystems (CMS, Legacy E-commerce, or Monolithic Portals). It enables you to inject modern React interactivity into any HTML-first environment without the risk of a full-stack migration.</p><h2 id="🏝️-island-architecture-selective-resumable-hydration" tabindex="-1">🏝️ Island Architecture: Selective &amp; Resumable Hydration <a class="header-anchor" href="#🏝️-island-architecture-selective-resumable-hydration" aria-label="Permalink to &quot;🏝️ Island Architecture: Selective &amp; Resumable Hydration&quot;">​</a></h2><p>Modern engineering is moving away from Monolithic SPAs toward <strong>Selective Hydration</strong>. <code>react-rehydrate</code> provides an architectural framework to implement this pattern in any legacy system:</p><ul><li><strong>Static Shell Strategy</strong>: Your server delivers 100% semantic HTML for instant indexing and SEO dominance.</li><li><strong>Interactive Islands (Isomorphism)</strong>: React roots &quot;rehydrate&quot; only high-value interactive zones.</li><li><strong>Selective Hydration</strong>: Only code present on the page is loaded and executed via dynamic imports.</li><li><strong>Resource Priority</strong>: Defer non-critical widgets while prioritizing LCP-critical interactivity.</li></ul><hr><h3 id="enterprise-technical-comparison-matrix" tabindex="-1">Enterprise Technical Comparison Matrix <a class="header-anchor" href="#enterprise-technical-comparison-matrix" aria-label="Permalink to &quot;Enterprise Technical Comparison Matrix&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Technical Dimension</th><th style="text-align:left;">React Rehydrate (Controlled Islands)</th><th style="text-align:left;">Legacy Monolith (jQuery/Server)</th><th style="text-align:left;">Modern SPA (Next/CRA/Vite)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SEO &amp; Indexability</strong></td><td style="text-align:left;">✅ Native / Instant</td><td style="text-align:left;">✅ Perfect</td><td style="text-align:left;">⚠️ High SSR Overhead</td></tr><tr><td style="text-align:left;"><strong>SMM Previews (OG Tags)</strong></td><td style="text-align:left;">✅ Static-First Ready</td><td style="text-align:left;">✅ Perfect</td><td style="text-align:left;">⚠️ Virtual / Meta Tags</td></tr><tr><td style="text-align:left;"><strong>Hydration Strategy</strong></td><td style="text-align:left;">✅ Selective &amp; Fragmented</td><td style="text-align:left;">❌ None</td><td style="text-align:left;">⚠️ Full Body Re-render</td></tr><tr><td style="text-align:left;"><strong>Core Web Vitals (CLS)</strong></td><td style="text-align:left;">✅ Zero-CLS Stability</td><td style="text-align:left;">✅ High Stability</td><td style="text-align:left;">❌ Frequent Hydration Shifts</td></tr><tr><td style="text-align:left;"><strong>Content Security Policy</strong></td><td style="text-align:left;">✅ Sanitized Bridge Root</td><td style="text-align:left;">❌ Large Attack Surface</td><td style="text-align:left;">⚠️ Moderate</td></tr><tr><td style="text-align:left;"><strong>Time to Interactive (TTI)</strong></td><td style="text-align:left;">✅ Optimized Selective Loading</td><td style="text-align:left;">✅ Fast</td><td style="text-align:left;">❌ Slow (Total JS Execution)</td></tr><tr><td style="text-align:left;"><strong>Memory Lifecycle</strong></td><td style="text-align:left;">✅ Disposable / GC-Ready Roots</td><td style="text-align:left;">✅ Efficient</td><td style="text-align:left;">⚠️ Risk of Memory Leaks</td></tr><tr><td style="text-align:left;"><strong>Development Experience</strong></td><td style="text-align:left;">✅ Full Vite / HMR Support</td><td style="text-align:left;">❌ Poor / Stale</td><td style="text-align:left;">✅ Excellent</td></tr><tr><td style="text-align:left;"><strong>Legacy JS Interop</strong></td><td style="text-align:left;">✅ Isolated Root Coexistence</td><td style="text-align:left;">✅ Native</td><td style="text-align:left;">❌ High Conflict</td></tr><tr><td style="text-align:left;"><strong>Micro-Frontend Autonomy</strong></td><td style="text-align:left;">✅ Drop-in Independent Roots</td><td style="text-align:left;">❌ Monolithic</td><td style="text-align:left;">⚠️ Orchestrated</td></tr><tr><td style="text-align:left;"><strong>Production Resilience</strong></td><td style="text-align:left;">✅ Multi-root Error Isolation</td><td style="text-align:left;">❌ No Safety Boundaries</td><td style="text-align:left;">✅ High</td></tr><tr><td style="text-align:left;"><strong>Discovery Performance</strong></td><td style="text-align:left;">✅ O(n) Non-blocking Scan</td><td style="text-align:left;">✅ Instant</td><td style="text-align:left;">❌ High Overhead</td></tr><tr><td style="text-align:left;"><strong>React 19 Native Actions</strong></td><td style="text-align:left;">✅ Full Modern Hook Support</td><td style="text-align:left;">❌ Incompatible</td><td style="text-align:left;">✅ Native</td></tr></tbody></table><hr><h2 id="⚡-react-rehydrate-vs-react-server-components-rsc" tabindex="-1">⚡ React Rehydrate vs. React Server Components (RSC) <a class="header-anchor" href="#⚡-react-rehydrate-vs-react-server-components-rsc" aria-label="Permalink to &quot;⚡ React Rehydrate vs. React Server Components (RSC)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Dimension</th><th style="text-align:left;">React Rehydrate</th><th style="text-align:left;">React Server Components (RSC)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Target Environment</strong></td><td style="text-align:left;">Brownfield / Legacy / Any CMS</td><td style="text-align:left;">Greenfield / Modern Server</td></tr><tr><td style="text-align:left;"><strong>Server Requirement</strong></td><td style="text-align:left;">Any (PHP, Ruby, .NET, Static)</td><td style="text-align:left;">Node.js (High integration)</td></tr><tr><td style="text-align:left;"><strong>Build Dependency</strong></td><td style="text-align:left;">Low (Bridge-only architecture)</td><td style="text-align:left;">High (Bundler-heavy)</td></tr><tr><td style="text-align:left;"><strong>Hydration Pattern</strong></td><td style="text-align:left;">Selective / Partially Resumable</td><td style="text-align:left;">Streamed</td></tr><tr><td style="text-align:left;"><strong>Legacy Interop</strong></td><td style="text-align:left;">✅ Excellence by Design</td><td style="text-align:left;">❌ High Friction</td></tr><tr><td style="text-align:left;"><strong>HMR Latency</strong></td><td style="text-align:left;">✅ Near-Zero (Vite-powered)</td><td style="text-align:left;">Low</td></tr></tbody></table><hr><h2 id="🏗️-architectural-lifecycle-middleware" tabindex="-1">🏗️ Architectural Lifecycle &amp; Middleware <a class="header-anchor" href="#🏗️-architectural-lifecycle-middleware" aria-label="Permalink to &quot;🏗️ Architectural Lifecycle &amp; Middleware&quot;">​</a></h2><p><code>react-rehydrate</code> implements a strictly managed handover between the static DOM and React:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[Static HTML] --&gt;|Scan| B[Discovery Phase]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|Match| C[Rehydrators]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|Fetch| D[Dynamic Chunks]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt;|Mount| E[Controlled Island]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt;|Interact| F[Updated State]</span></span></code></pre></div><h3 id="_1-the-rehydrator-transform-pattern" tabindex="-1">1. The Rehydrator Transform Pattern <a class="header-anchor" href="#_1-the-rehydrator-transform-pattern" aria-label="Permalink to &quot;1. The Rehydrator Transform Pattern&quot;">​</a></h3><p>We explicitly decouple your components from the DOM. A <strong>Rehydrator</strong> is an asynchronous middleware layer that acts as a transform between human-readable markup and component props. This keeps your React library platform-agnostic.</p><h3 id="_2-multi-root-fault-tolerance" tabindex="-1">2. Multi-Root Fault Tolerance <a class="header-anchor" href="#_2-multi-root-fault-tolerance" aria-label="Permalink to &quot;2. Multi-Root Fault Tolerance&quot;">​</a></h3><p>By using independent <strong>React Roots</strong>, we provide &quot;domain isolation.&quot; A crash in a non-critical sidebar widget cannot brick your checkout flow or global navigation. This is essential for high-availability enterprise sites.</p><h3 id="_3-sustainability-efficiency" tabindex="-1">3. Sustainability &amp; Efficiency <a class="header-anchor" href="#_3-sustainability-efficiency" aria-label="Permalink to &quot;3. Sustainability &amp; Efficiency&quot;">​</a></h3><p>By executing less JavaScript and avoiding full page re-renders, <code>react-rehydrate</code> reduces CPU cycles and energy consumption. This is a step toward a high-performance, sustainability-focused frontend.</p><hr><h2 id="🚀-why-react-rehydrate-vs-other-libraries" tabindex="-1">🚀 Why React Rehydrate vs. Other Libraries? <a class="header-anchor" href="#🚀-why-react-rehydrate-vs-other-libraries" aria-label="Permalink to &quot;🚀 Why React Rehydrate vs. Other Libraries?&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">High-Level Feature</th><th style="text-align:left;">React Rehydrate</th><th style="text-align:left;">Legacy <code>react-from-markup</code></th><th style="text-align:left;">Frameworks (Astro/Qwik)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>React 18/19 Support</strong></td><td style="text-align:left;">✅ Cutting Edge (React 19)</td><td style="text-align:left;">❌ Stale (V16)</td><td style="text-align:left;">✅ Full</td></tr><tr><td style="text-align:left;"><strong>Migration Risk</strong></td><td style="text-align:left;">✅ Zero-Friction Drop-in</td><td style="text-align:left;">Low</td><td style="text-align:left;">❌ High (Total rewrite)</td></tr><tr><td style="text-align:left;"><strong>Build System</strong></td><td style="text-align:left;">✅ Build System Agnostic</td><td style="text-align:left;">✅ Any</td><td style="text-align:left;">❌ Strict pipeline lock-in</td></tr><tr><td style="text-align:left;"><strong>Nested Strategy</strong></td><td style="text-align:left;">✅ Native Recursive Support</td><td style="text-align:left;">❌ None</td><td style="text-align:left;">⚠️ Recursive difficulty</td></tr><tr><td style="text-align:left;"><strong>Resumability Support</strong></td><td style="text-align:left;">✅ Partial (Post-Discovery)</td><td style="text-align:left;">❌ No</td><td style="text-align:left;">✅ Selective</td></tr></tbody></table><hr><h2 id="📖-deep-dives" tabindex="-1">📖 Deep Dives <a class="header-anchor" href="#📖-deep-dives" aria-label="Permalink to &quot;📖 Deep Dives&quot;">​</a></h2><ul><li><a href="/react-rehydrate/architecture.html"><strong>The Blueprint</strong></a> — Architectural overview &amp; value proposition.</li><li><a href="/react-rehydrate/installation.html"><strong>Installation</strong></a> — Get started in under 5 minutes.</li><li><a href="/react-rehydrate/guides/script-integration.html"><strong>Script Integration</strong></a> — The path to drop-in interactivity.</li><li><a href="/react-rehydrate/containers.html"><strong>Core Fundamentals</strong></a> — Mastering containers &amp; rehydrators.</li><li><a href="/react-rehydrate/rehydrators/dynamic-rehydratable-name.html"><strong>Advanced Patterns</strong></a> — Dynamic resolution &amp; async loading.</li><li><a href="/react-rehydrate/demos/index.html"><strong>React 19 Demos</strong></a> — Engineering examples in action.</li></ul>`,28)])])}const f=e(i,[["render",n]]);export{h as __pageData,f as default};
